const crypto = require("crypto");

function signRequest({ method, path, query, rawBody, timestamp, nonce, clientSecret }) {
  const normalizedQuery = new URLSearchParams(query || "");
  const sortedQuery = [...normalizedQuery.entries()]
    .sort((a, b) => (a[0] + a[1]).localeCompare(b[0] + b[1]))
    .map(([k, v]) => `${k}=${v}`)
    .join("&");

  const bodyHash = crypto.createHash("sha256").update(rawBody || "", "utf8").digest("hex");
  const canonical = [method.toUpperCase(), path, sortedQuery, bodyHash, timestamp, nonce].join("\n");

  return crypto.createHmac("sha256", clientSecret).update(canonical, "utf8").digest("base64");
}

function sign_request($method, $path, $queryString, $rawBody, $timestamp, $nonce, $clientSecret) {
    parse_str($queryString ?: "", $query);
    ksort($query);
    $normalizedQuery = http_build_query($query, "", "&", PHP_QUERY_RFC3986);

    $bodyHash = hash("sha256", $rawBody ?: "");
    $canonical = strtoupper($method) . "\n" . $path . "\n" . $normalizedQuery . "\n" . $bodyHash . "\n" . $timestamp . "\n" . $nonce;

    $hmac = hash_hmac("sha256", $canonical, $clientSecret, true);
    return base64_encode($hmac);
}

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public static String signRequest(String canonical, String clientSecret) throws Exception {
    Mac hmac = Mac.getInstance("HmacSHA256");
    hmac.init(new SecretKeySpec(clientSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
    byte[] digest = hmac.doFinal(canonical.getBytes(StandardCharsets.UTF_8));
    return Base64.getEncoder().encodeToString(digest);
}

using System.Security.Cryptography;
using System.Text;

public static string SignRequest(string canonical, string clientSecret)
{
    using var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(clientSecret));
    var digest = hmac.ComputeHash(Encoding.UTF8.GetBytes(canonical));
    return Convert.ToBase64String(digest);
}

import (
    "crypto/hmac"
    "crypto/sha256"
    "encoding/base64"
)

func SignRequest(canonical string, clientSecret string) string {
    mac := hmac.New(sha256.New, []byte(clientSecret))
    mac.Write([]byte(canonical))
    return base64.StdEncoding.EncodeToString(mac.Sum(nil))
}

const axios = require("axios");
const crypto = require("crypto");

async function createIntent() {
    const method = "POST";
    const path = "/api/v1/payments/intents";
    const body = JSON.stringify({
        provider: "surpay_fronterizo",
        amount: 12000,
        currency: "CLP",
        external_order_id: "txn_123456",
        expires_in: 900,
        concept: "Compra API",
        qr_from: "AR"
    });

    const ts = Math.floor(Date.now() / 1000).toString();
    const nonce = crypto.randomUUID();
    const idem = crypto.randomUUID();
    const signature = signRequest({ method, path, query: "", rawBody: body, timestamp: ts, nonce, clientSecret: process.env.CLIENT_SECRET });

    const res = await axios.post(`${process.env.BASE_URL}${path}`, body, {
        headers: {
            "Content-Type": "application/json",
            "X-Client-Id": process.env.CLIENT_ID,
            "X-Timestamp": ts,
            "X-Nonce": nonce,
            "X-Signature": signature,
            "Idempotency-Key": idem
        }
    });
    return res.data;
}

function generate_uuid_v4() {
    $data = random_bytes(16);
    $data[6] = chr((ord($data[6]) & 0x0f) | 0x40);
    $data[8] = chr((ord($data[8]) & 0x3f) | 0x80);
    return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($data), 4));
}

function sign_request($method, $path, $queryString, $rawBody, $timestamp, $nonce, $clientSecret) {
    parse_str($queryString ?: "", $query);
    ksort($query);
    $normalizedQuery = http_build_query($query, "", "&", PHP_QUERY_RFC3986);

    $bodyHash = hash("sha256", $rawBody ?: "");
    $canonical = strtoupper($method) . "\n" . $path . "\n" . $normalizedQuery . "\n" . $bodyHash . "\n" . $timestamp . "\n" . $nonce;

    $hmac = hash_hmac("sha256", $canonical, $clientSecret, true);
    return base64_encode($hmac);
}

