$clientId = "TU_CLIENT_ID";
$clientSecret = "TU_CLIENT_SECRET";

$path = "/api/v1/payments/intents";
$payload = json_encode([
    "provider" => "surpay_fronterizo",
    "amount" => 12000,
    "currency" => "CLP",
    "external_order_id" => "txn_123456",
    "expires_in" => 900,
    "concept" => "Compra API",
    "qr_from" => "AR"
]);

$timestamp = strval(time());
$nonce = generate_uuid_v4();
$idempotency = generate_uuid_v4();
$signature = sign_request("POST", $path, "", $payload, $timestamp, $nonce, $clientSecret);

$headers = [
    "Content-Type: application/json",
    "X-Client-Id: $clientId",
    "X-Timestamp: $timestamp",
    "X-Nonce: $nonce",
    "X-Signature: $signature",
    "Idempotency-Key: $idempotency"
];

$ch = curl_init($baseUrl . $path);
curl_setopt($ch, CURLOPT_POST, true);
curl_setopt($ch, CURLOPT_POSTFIELDS, $payload);
curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
$response = curl_exec($ch);
$statusCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);

if ($response === false) {
    throw new RuntimeException("cURL error: " . curl_error($ch));
}

curl_close($ch);
$data = json_decode($response, true);

if ($statusCode >= 400) {
    throw new RuntimeException("API error " . $statusCode . ": " . $response);
}

print_r($data);

